document.addEventListener('click',e=>{let x=e.target.closest('[data-act]');if(!x)return;e.preventDefault();dispatch(x.dataset.act,x).catch(err=>toast(err.message,true))});
document.addEventListener('submit',e=>{if(e.target.id!=='create-form')return;e.preventDefault();let form=Object.fromEntries(new FormData(e.target).entries());busyRun(async()=>{const r=await api('/api/projects',{method:'POST',body:form});S.modal='';S.project=r.project;S.view='ideas';const d=await api('/api/projects/'+r.project.id+'/develop',{method:'POST',body:{mode:'demo'}});S.project=d.project;await refresh();toast('Nowa kampania gotowa do pracy.');})});
(async function init(){try{S.health=await api('/api/health');const list=await api('/api/projects');S.projects=list.projects||[];if(S.projects.length)await openProject(S.projects[0].id);const personas=await api('/api/personas');S.personas=personas.personas||[];S.styleGuide=await api('/api/style-guide');paint()}catch(e){if(S.health.protected){S.modal='auth';paint()}else{$('#app').innerHTML='<div class="boot">Nie udało się uruchomić aplikacji. Sprawdź terminal serwera.</div>';toast(e.message,true)}}if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{});})();
